css:
/* categories v2 */
.cats4{grid-template-columns:repeat(4,1fr)!important}
.cat-big{display:flex;flex-direction:column;gap:12px;padding:22px 20px 18px}
.cat-big:hover{transform:none;box-shadow:none}
.cat-main{color:#1d1d1f !important;text-decoration:none !important}
.cat-main b{display:block;font-size:19px;margin-top:10px}
.cat-main span{font-size:14px;color:#6e6e73}
.subs{display:flex;flex-wrap:wrap;gap:6px}
.subs a{background:#fff;border:1px solid #e8e8ed;border-radius:999px;padding:5px 11px;font-size:13px;font-weight:600;color:#1d1d1f !important;text-decoration:none !important}
.subs a:hover{border-color:#1d1d1f}
.cat-gift{background:#1d1d1f !important}
.cat-gift .cat-main,.cat-gift .cat-main b{color:#fff !important}
.cat-gift .cat-main span{color:#c7c7cc}
/* search */
.nav-search{display:flex;align-items:center;margin-left:auto;margin-right:12px}
.nav-search input{width:170px;border:1px solid #d2d2d7;border-radius:999px;padding:7px 14px;font-size:14px;background:#f5f5f7;outline:none;font-family:inherit}
.nav-search input:focus{background:#fff;border-color:#1d1d1f;width:220px}
@media (max-width:900px){.cats4{grid-template-columns:repeat(2,1fr)!important}}
@media (max-width:640px){.cats4{grid-template-columns:1fr!important}.nav-search{margin-right:8px}.nav-search input{width:120px;padding:6px 11px;font-size:13px}.nav-search input:focus{width:150px}}
